func:
let stats = flow.get('bme_stats') || {
  t_min: 999, t_max: -999, t_sum: 0, count: 0,
  h_min: 999, h_max: -999, h_sum: 0,
  p_min: 9999, p_max: -9999, p_sum: 0
};

let d = msg.payload;
stats.count++;

stats.t_min = Math.min(stats.t_min, d.temperature);
stats.t_max = Math.max(stats.t_max, d.temperature);
stats.t_sum += d.temperature;

stats.h_min = Math.min(stats.h_min, d.humidity);
stats.h_max = Math.max(stats.h_max, d.humidity);
stats.h_sum += d.humidity;

stats.p_min = Math.min(stats.p_min, d.pressure);
stats.p_max = Math.max(stats.p_max, d.pressure);
stats.p_sum += d.pressure;

flow.set('bme_stats', stats);

msg.payload = {
  Temperature: { min: stats.t_min, max: stats.t_max, avg: +(stats.t_sum / stats.count).toFixed(2) },
  Humidity: { min: stats.h_min, max: stats.h_max, avg: +(stats.h_sum / stats.count).toFixed(2) },
  Pressure: { min: stats.p_min, max: stats.p_max, avg: +(stats.p_sum / stats.count).toFixed(2) }
};
return msg;
